cam=[3.5,.10,2.7];pitch=math.radians(22);hfov=126;f=1/(2*math.tan(math.radians(hfov/2)));fy=f*16/9
def project(x,y,z):
 dx,dy,dz=x-cam[0],y-cam[1],z-cam[2];depth=math.cos(pitch)*dy-math.sin(pitch)*dz;up=math.sin(pitch)*dy+math.cos(pitch)*dz
 return [round(.5+f*dx/depth,5),round(.5-fy*up/depth,5)]
